def get_func_in_module(module: str, qualname: str) ->Callable[..., Any]:
    obj = get_name_in_module(module, qualname)
    if isinstance(obj, types.MethodType):
        obj = obj.__func__
    elif isinstance(obj, property):
        if obj.fset is not None or obj.fdel is not None:
            raise InvalidTypeError(
                f"Cannot get function for property with setter or deleter: {qualname}"
            )
        obj = obj.fget
    if not callable(obj):
        raise InvalidTypeError(
            f"Object at {qualname} in {module} is not callable: {obj!r}"
        )
    return obj


def get_name_in_module(module: str, qualname: str, attr_getter: Optional[
    Callable[[Any, str], Any]]=None) ->Any:
    if attr_getter is None:
        attr_getter = getattr
    try:
        obj = importlib.import_module(module)
    except ImportError as e:
        raise NameLookupError(f"Cannot import module {module}") from e
    parts = qualname.split(".")
    for part in parts:
        try:
            obj = attr_getter(obj, part)
        except AttributeError as e:
            raise NameLookupError(
                f"Cannot find {qualname} in module {module}: {e}"
            ) from e
    return obj
